  /**
   * Test {@link SQLStandardParser#SQLStandardParser(TokenStream)}.
   *
   * <p>Method under test: {@link SQLStandardParser#SQLStandardParser(TokenStream)}
   */
  @Test
  @Category(ContributionFromDiffblue.class)
  @ManagedByDiffblue
  @MethodsUnderTest({"void SQLStandardParser.<init>(TokenStream)"})
  public void testNewSQLStandardParser() {
    // Arrange
    SQLStandardLexer tokenSource = new SQLStandardLexer(new ANTLRInputStream("Input"));
    BufferedTokenStream input = new BufferedTokenStream(tokenSource);

    // Act
    SQLStandardParser actualSqlStandardParser = new SQLStandardParser(input);

    // Assert
    TokenStream inputStream = actualSqlStandardParser.getInputStream();
    assertTrue(inputStream instanceof BufferedTokenStream);
    assertTrue(actualSqlStandardParser.getCurrentToken() instanceof CommonToken);
    assertTrue(actualSqlStandardParser.getTokenFactory() instanceof CommonTokenFactory);
    assertTrue(actualSqlStandardParser.getErrorHandler() instanceof DefaultErrorStrategy);
    assertTrue(actualSqlStandardParser.getErrorListenerDispatch() instanceof ProxyErrorListener);
    Vocabulary vocabulary = actualSqlStandardParser.getVocabulary();
    assertTrue(vocabulary instanceof VocabularyImpl);
    assertEquals("<unknown>", actualSqlStandardParser.getSourceName());
    assertEquals("SQLStandardParser.g4", actualSqlStandardParser.getGrammarFileName());
    assertNull(actualSqlStandardParser.getContext());
    assertNull(actualSqlStandardParser.getRuleContext());
    assertNull(actualSqlStandardParser.getParseInfo());
    assertEquals(-1, actualSqlStandardParser.getState());
    assertEquals(0, actualSqlStandardParser.getNumberOfSyntaxErrors());
    assertEquals(0, actualSqlStandardParser.getPrecedence());
    assertEquals(1, actualSqlStandardParser.getErrorListeners().size());
    Map<String, Integer> ruleIndexMap = actualSqlStandardParser.getRuleIndexMap();
    assertEquals(289, ruleIndexMap.size());
    assertEquals(360, actualSqlStandardParser.getDFAStrings().size());
    assertFalse(actualSqlStandardParser.getTrimParseTree());
    assertFalse(actualSqlStandardParser.isMatchedEOF());
    assertFalse(actualSqlStandardParser.isTrace());
    assertTrue(actualSqlStandardParser.getParseListeners().isEmpty());
    assertTrue(actualSqlStandardParser.getRuleInvocationStack().isEmpty());
    assertTrue(ruleIndexMap.containsKey("matchType"));
    assertTrue(ruleIndexMap.containsKey("matchValue"));
    assertTrue(ruleIndexMap.containsKey("namedParameter"));
    assertTrue(ruleIndexMap.containsKey("schemaDefinition"));
    assertTrue(ruleIndexMap.containsKey("setQuantifier"));
    assertTrue(ruleIndexMap.containsKey("tableName"));
    Map<String, Integer> tokenTypeMap = actualSqlStandardParser.getTokenTypeMap();
    assertEquals(SQLStandardParser.RULE_setTargetList, tokenTypeMap.size());
    assertTrue(tokenTypeMap.containsKey("'-'"));
    assertTrue(tokenTypeMap.containsKey("'>'"));
    assertTrue(tokenTypeMap.containsKey("'_'"));
    assertTrue(tokenTypeMap.containsKey("BETWEEN"));
    assertTrue(tokenTypeMap.containsKey("CREATE"));
    assertTrue(tokenTypeMap.containsKey("MONTH"));
    assertTrue(actualSqlStandardParser.getBuildParseTree());
    assertEquals(SQLStandardParser._serializedATN, actualSqlStandardParser.getSerializedATN());
    assertSame(input, inputStream);
    assertSame(input, actualSqlStandardParser.getTokenStream());
    assertSame(SQLStandardParser.VOCABULARY, vocabulary);
    assertSame(SQLStandardParser._ATN, actualSqlStandardParser.getATN());
    assertSame(SQLStandardParser.ruleNames, actualSqlStandardParser.getRuleNames());
    assertSame(SQLStandardParser.tokenNames, actualSqlStandardParser.getTokenNames());
  }

